// Snippets trimmed from files generated by Poetry 2.5.1 and uv 0.13.7.

const poetryPyproject = `[tool.poetry]
name = "ml-poetry"
package-mode = false

[tool.poetry.dependencies]
python = "^3.10"
requests = "2.19.0"
Jinja2 = "2.10"

[tool.poetry.group.dev.dependencies]
pytest = "7.0.0"
`

const poetryLock2 = `# This file is automatically @generated by Poetry 2.5.1 and should not be changed by hand.

[[package]]
name = "attrs"
version = "26.1.0"
optional = false
groups = ["dev"]

[[package]]
name = "jinja2"
version = "2.10"
groups = ["main"]

[[package]]
name = "pytest"
version = "7.0.0"
groups = ["dev"]

[[package]]
name = "requests"
version = "2.19.0"
groups = ["main"]

[[package]]
name = "urllib3"
version = "1.23"
groups = ["main", "dev"]

[[package]]
name = "mylib"
version = "0.1.0"
groups = ["main"]

[package.source]
type = "directory"
url = "../mylib"

[metadata]
lock-version = "2.1"
`

const poetryLock1 = `[[package]]
name = "requests"
version = "2.19.0"
category = "main"

[[package]]
name = "pytest"
version = "7.0.0"
category = "dev"

[[package]]
name = "py"
version = "1.11.0"
category = "dev"

[metadata]
lock-version = "1.1"
`

func TestPoetryLockParser(t *testing.T) {
	for name, tc := range map[string]struct {
		lock string
		want map[string][2]bool
	}{
		"poetry2-groups": {poetryLock2, map[string][2]bool{
			"attrs@26.1.0":    {false, true},
			"jinja2@2.10":     {true, false},
			"pytest@7.0.0":    {true, true},
			"requests@2.19.0": {true, false},
			"urllib3@1.23":    {false, false}, // in main and dev → production
		}},
		"poetry1-category": {poetryLock1, map[string][2]bool{
			"requests@2.19.0": {true, false},
			"pytest@7.0.0":    {true, true},
			"py@1.11.0":       {false, true},
		}},
	} {
		t.Run(name, func(t *testing.T) {
			root := writeFiles(t, map[string]string{"pyproject.toml": poetryPyproject, "poetry.lock": tc.lock})
			res, err := PoetryLockParser{}.Parse(filepath.Join(root, "poetry.lock"), "poetry.lock")
			if err != nil {
				t.Fatal(err)
			}
			checkPyComponents(t, res.Components, tc.want)
		})
	}
}

